// --- Build the exact MQTT Topic ---
let gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";
msg.topic = `gateway/${gatewaySerial}/power/out`;

return msg;

let raw = msg.payload.data || msg.payload;

if (raw && raw.length >= 2) {
    // 1. Stitch the two 16-bit Modbus registers into a 32-bit signed integer
    let weight = (raw[0] << 16) | raw[1];

    // 2. Dynamically pull the device's hardware serial from the local .env
    let gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

    // 3. Format the payload to exactly match your Tinymesh backend architecture
