msg.payload = msg.payload.weight;
let val = parseInt(msg.payload);

// Safety guard: prevent NaN or negative nominal values
if (isNaN(val) || val <= 0) return null; 

// Convert the user's weight input into two 16-bit Modbus words
let highWord = (val >> 16) & 0xFFFF;
let lowWord = val & 0xFFFF;

msg.payload = [highWord, lowWord];

// Safely parse the dropdown string into an integer Unit ID
