// ── FAI Gateway Parser (v7.3 - Always-send weight, "now" timestamp, GASCO2 workaround) ──
//
// Key fix vs v6.0: the backend does NOT want JSON in `data`. It wants the raw
// hex-encoded C-struct (sensor_telegram_t / weight array), exactly like the
// physical Tinymesh hardware sent it, with detail:"serial".
//
// Changes in v7.3 (app showed device online but no weight/graph data):
//   1. Removed the weight>0.01 guard on Packet 2 — always send the weight
//      array now, including 0g, matching confirmed old-hardware behavior.
//   2. Timestamp reverted to always-"now" (matches proven v3.1 behavior)
//      instead of preferring ChirpStack's uplink time — removes possible
//      clock-skew/query-window mismatch as a variable.
// Note: a "send a fake 0x04 keep-alive packet to flip online status" fix
// was considered and rejected — the device already shows online in the app,
// so that diagnosis didn't match the actual symptom. Not included here.
//
// Per the official sensors.h spec:
//   Type 0x01 (Env, 58 bytes): all fields Little-Endian Float32, except
//     LightALS (bytes 22-25) which is Uint32 LE.
//   Type 0x02 (Weight, 106 bytes): 50x Uint16 LE samples starting at byte 6.
//
// CONFIRMED WORKAROUND: the third-party backend's decoder reads GASCO2
// (bytes 26-29) as Uint32, not Float32 as the spec documents. We can't patch
// the backend, so this parser writes GASCO2 as a raw integer to match what
// the backend actually does, not what the spec says it should do. See the
// inline comment at that field for the verification details.

const gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";
const TARGET_CLOUD_SID = 16777216;

if (!msg.payload || !msg.payload.deviceInfo || !msg.payload.data) return null;

// ── UID: last 4 bytes of DevEUI, Big-Endian (matches dynamicUid convention) ──
const devEui = msg.payload.deviceInfo.devEui;
const uidHex = devEui.slice(-8);
const dynamicUid = parseInt(uidHex, 16);

// ── Decode the LoRa binary payload ──
// Payload is now 22 bytes (was 14, was originally 10): the Arduino sketch
// now also transmits humidity and pressure from the already-installed
// BME280 (it measures both, the code just wasn't reading them before).
// Layout, all Little-Endian:
//   bytes 0-3:   temperature (float)
//   bytes 4-5:   co2 ppm (uint16)
//   bytes 6-9:   scale weight (float)
//   bytes 10-13: light lux (float)
//   bytes 14-17: humidity %RH (float)   <-- NEW
//   bytes 18-21: pressure hPa (float)   <-- NEW
const buf = Buffer.from(msg.payload.data, 'base64');
if (buf.length < 22) return null;

const temp     = buf.readFloatLE(0);   // °C
const co2      = buf.readUInt16LE(4);  // ppm
const weight   = buf.readFloatLE(6);   // g
const lux      = buf.readFloatLE(10);  // lx
const humidity = buf.readFloatLE(14);  // %RH
const pressure = buf.readFloatLE(18);  // hPa

// ── RSSI & meta (raw integer, matching tinymesh-edge convention: Math.abs) ──
let bestRssi = -120;
if (msg.payload.rxInfo && msg.payload.rxInfo.length > 0) {
    bestRssi = Math.max(...msg.payload.rxInfo.map(rx => rx.rssi));
}
const rawRssi = Math.abs(bestRssi);
// Timestamp: match the known-working v3.1 behavior exactly. v3.1 always used
// "now" (the time Node-RED processed the packet), never the radio's own
// embedded timestamp. We previously preferred msg.payload.time (ChirpStack's
// uplink receive time) as a "more accurate" timestamp, but that's an
// unverified deviation from what's proven to work — if there's any clock
// skew between the Jetson and the app's backend, or if the app's query
// window is strict about recency, this could be why weight data silently
// fails to render in the app even though Grafana (likely more lenient on
// time range) still shows it. Reverting to "always now" removes that as a
// variable.
const timestamp = new Date().toISOString().split('.')[0] + '+00:00';

const outMessages = [];

// ==========================================
// FORGE PACKET 1: TYPE 0x01 (ENVIRONMENTAL)
// Length: 58 bytes | Signature: 013a
// Layout matches sensor_telegram_t exactly, Little-Endian floats per sensors.h spec
// ==========================================
const envBuf = Buffer.alloc(58, 0);
envBuf.writeUInt8(0x01, 0); // Byte 0: Type
envBuf.writeUInt8(0x3a, 1); // Byte 1: Length (58)

// Bytes 2-5 reserved/unused in struct — left as 0x00

envBuf.writeFloatLE(temp, 6);    // AirTemperature      (bytes 6-9)
envBuf.writeFloatLE(pressure, 10); // AirPressure (bytes 10-13) — now real BME280 hPa reading.
                                  // UNVERIFIED against backend: AirTemperature at byte 6 is
                                  // confirmed correct as Float32, but we haven't specifically
                                  // checked AirPressure. If Grafana shows nonsense here, run the
                                  // same bit-pattern check used for GASCO2.
envBuf.writeFloatLE(temp, 14);   // HumidityTemperature  (bytes 14-17)  — BME280 has one temp sensor,
                                  // reused here since there's no separate humidity-specific probe
envBuf.writeFloatLE(humidity, 18); // Humidity (bytes 18-21) — now real BME280 %RH reading.
                                  // Also unverified against backend — check Grafana after deploy.
envBuf.writeUInt32LE(Math.max(0, Math.round(lux)), 22); // LightALS (bytes 22-25) — now real VEML7700
                                            // lux data. Written as Uint32 per spec (rounded, floor
                                            // 0 since lux can't be negative). UNVERIFIED: we found
                                            // GASCO2 doesn't match its documented type, so once this
                                            // is live, check Grafana the same way — if LightALS shows
                                            // a nonsense number, the backend likely also reads this
                                            // field as a different type than Uint32 and needs the
                                            // same bit-pattern diagnosis we did for GASCO2.
envBuf.writeUInt32LE(Math.round(co2), 26); // GASCO2 (bytes 26-29) — WORKAROUND: spec sheet says
                                            // Float32 here, but the backend's fixed/third-party
                                            // decoder actually reads this field as Uint32 (same
                                            // type as LightALS next to it). Confirmed by reverse-
                                            // engineering: writing 476.0 as Float32 produced
                                            // 1139671040 in Grafana — the exact bit pattern of
                                            // that float reinterpreted as a raw uint32. Since the
                                            // backend can't be patched, we match its real behavior
                                            // instead of the documented spec: write the ppm value
                                            // directly as an integer.
envBuf.writeFloatLE(0.0, 30);    // GASTemperature       (bytes 30-33)
envBuf.writeFloatLE(0.0, 34);    // GASHumidity          (bytes 34-37)
envBuf.writeFloatLE(0.0, 38);    // GASNH3               (bytes 38-41)
envBuf.writeFloatLE(0.0, 42);    // GASCO                (bytes 42-45)
envBuf.writeFloatLE(0.0, 46);    // GASNO2               (bytes 46-49)
envBuf.writeFloatLE(temp, 50);   // BoardTemperature     (bytes 50-53)  — reuse BME280 temp
envBuf.writeFloatLE(temp, 54);   // PT100Temperature     (bytes 54-57)  — reuse BME280 temp

outMessages.push({
    topic: `gateway/${gatewaySerial}/tinymesh/out`,
    payload: {
        "_meta": { "received": timestamp },
        "block": 0,
        "data": envBuf.toString('hex'), // RAW HEX — backend decodes this itself
        "detail": "serial",             // matches the proven working contract
        "hops": 1,
        "latency": 2,
        "network_lvl": 1,
        "packet_num": Math.floor(Math.random() * 65535), // bypass cloud dedup
        "rssi": rawRssi,
        "sid": TARGET_CLOUD_SID,
        "type": "event",
        "uid": dynamicUid
    }
});

// ==========================================
// FORGE PACKET 2: TYPE 0x02 (WEIGHT ARRAY)
// Length: 106 bytes | Signature: 026a
// Array of 50x UInt16, Little-Endian (per reference decoder: "Payload stays LE")
//
// NOTE: previously guarded with `if (weight > 0.01 || weight < -0.01)` to
// skip sending when the scale read ~0g. Removed: confirmed that old hardware
// always sent weight including 0g, and the app is expected to show the scale
// dropping to zero (e.g. bird stepped off), not flatline at the last nonzero
// reading. Always transmit this packet now.
// ==========================================
{
    const wBuf = Buffer.alloc(106, 0);
    wBuf.writeUInt8(0x02, 0); // Byte 0: Type
    wBuf.writeUInt8(0x6a, 1); // Byte 1: Length (106)

    const wInt = Math.abs(Math.round(weight));

    for (let i = 0; i < 50; i++) {
        wBuf.writeUInt16LE(wInt, 6 + (i * 2));
    }

    outMessages.push({
        topic: `gateway/${gatewaySerial}/tinymesh/out`,
        payload: {
            "_meta": { "received": timestamp },
            "block": 0,
            "data": wBuf.toString('hex'), // RAW HEX, same as packet 1
            "detail": "serial",
            "hops": 1,
            "latency": 2,
            "network_lvl": 1,
            "packet_num": Math.floor(Math.random() * 65535),
            "rssi": rawRssi,
            "sid": TARGET_CLOUD_SID,
            "type": "event",
            "uid": dynamicUid
        }
    });
}

return [ outMessages ];

let raw = msg.payload.data || msg.payload;

if (raw && raw.length >= 2) {
    let weight = (raw[0] << 16) | raw[1];

    let gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

    // Hardcode the Device ID for Silo 1
    let deviceId = `${gatewaySerial}-silo1`;

    msg.payload = {
        "gateway_id": gatewaySerial,
        "device_id": deviceId,
        "sensor_type": "silo_weight",
        "timestamp": new Date().toISOString(),
        "data": {
            "weight_kg": weight
        }
    };

    msg.topic = `gateway/${gatewaySerial}/silo/${deviceId}/telemetry`;
    return msg;
}
return null;

// Simulate a standard LoRaWAN uplink packet that matches the LoRa Parser 7.2 requirements
// The parser needs: msg.payload.deviceInfo AND msg.payload.data
// Data is a 22-byte base64 encoded buffer

const buf = Buffer.alloc(22, 0);
// Randomize data to prevent payload deduping
buf.writeFloatLE(Math.random() * 30, 0); // Temp
buf.writeUInt16LE(400, 4);               // CO2

msg.payload = {
    "deviceInfo": { "devEui": "c6ceb21d3fdfb40f" },
    "data": buf.toString('base64'),
    "rxInfo": [{ "rssi": -50, "snr": 10 }]
};
return msg;

// ── The Complete 18-Byte Header Parser (Env, Weight, Alive, Light & Spot) ──

const gatewayId = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";
const TARGET_CLOUD_SID = 16777216; 

let incoming = "";
if (Buffer.isBuffer(msg.payload)) incoming = msg.payload.toString('hex');
else if (msg.payload && typeof msg.payload.hex === 'string') incoming = msg.payload.hex;
else if (typeof msg.payload === 'string') incoming = msg.payload;
else return null;

let buf = (context.get('buf') || '') + incoming.replace(/\s+/g, '');
const out = [];

// 1. GARBAGE COLLECTOR
if (buf.length > 8192) {
    buf = ""; 
    context.set('buf', buf);
    node.warn("Buffer overflow prevented. Flushed garbage data.");
    return null;
}

// 2. OMNI-SIGNATURE SCANNER
while (buf.length > 0) {
    // Look for all known packet types
    let sensorIdx = buf.indexOf("013a"); // Type 0x01 (Env), Length 58
    let weightIdx = buf.indexOf("026a"); // Type 0x02 (Weight Array), Length 106
    let aliveIdx  = buf.indexOf("040c"); // Type 0x04 (Alive), Length 12
    let lightIdx  = buf.indexOf("070a"); // Type 0x07 (SEN0562), Length 10
    let spotIdx   = buf.indexOf("0808"); // Type 0x08 (Weight Spot), Length 8

    let startIndex = -1;
    let packetType = 0;

    // Find whichever valid signature appears first in the current chunk
    const indices = [
        { type: 1, idx: sensorIdx },
        { type: 2, idx: weightIdx },
        { type: 4, idx: aliveIdx },
        { type: 7, idx: lightIdx },
        { type: 8, idx: spotIdx }
    ].filter(obj => obj.idx !== -1);

    if (indices.length > 0) {
        const earliest = indices.reduce((prev, curr) => prev.idx < curr.idx ? prev : curr);
        startIndex = earliest.idx;
        packetType = earliest.type;
    }

    if (startIndex === -1) {
        if (buf.length > 50) buf = buf.slice(-50);
        break; 
    }

    // 3. EXTRACT THE 18-BYTE PACKET MODE HEADER
    if (startIndex < 36) {
        buf = buf.slice(startIndex + 2); 
        continue;
    }

    const headerHex = buf.slice(startIndex - 36, startIndex); 

    // ── THE BIG-ENDIAN FIX ──
    const trueUidHex = headerHex.slice(10, 18);
    let dynamicUid = 0; 
    if (/^[0-9a-fA-F]{8}$/.test(trueUidHex)) {
        dynamicUid = Buffer.from(trueUidHex, 'hex').readUInt32BE(0); 
    } else {
        buf = buf.slice(startIndex + 2);
        continue;
    }

    // ── EXTRACT METADATA ──
    const trueRssiHex = headerHex.slice(18, 20);
    let rawRssi = parseInt(trueRssiHex, 16);
    let trueRssi = (rawRssi / 2) - 121; // Match the old Gateway's exact dBm formula

    const networkLvl = parseInt(headerHex.slice(20, 22), 16) || 1;
    const hops = parseInt(headerHex.slice(22, 24), 16) || 1;
    const latency = parseInt(headerHex.slice(24, 26), 16) || 2;

    // 4. EXTRACT THE PAYLOAD DATA (Little-Endian)
    let expectedPayloadChars = 0;
    if (packetType === 1) expectedPayloadChars = 58 * 2;
    else if (packetType === 2) expectedPayloadChars = 106 * 2;
    else if (packetType === 4) expectedPayloadChars = 12 * 2;
    else if (packetType === 7) expectedPayloadChars = 10 * 2;
    else if (packetType === 8) expectedPayloadChars = 8 * 2;

    if (buf.length < startIndex + expectedPayloadChars) {
        break; // Wait for the rest of the serial chunk
    }

    const frameHex = buf.slice(startIndex, startIndex + expectedPayloadChars);
    buf = buf.slice(startIndex + expectedPayloadChars); 

    const bytes = [];
    for (let i = 0; i < frameHex.length; i += 2) {
        bytes.push(parseInt(frameHex.slice(i, i + 2), 16));
    }
    const view = new DataView(new Uint8Array(bytes).buffer);

    let extractedData = {};
    let messageDetail = "unknown";

    if (packetType === 1) {
        messageDetail = "sensor_telemetry";
        extractedData = {
            AirTemperature:      view.getFloat32(6,  true),
            AirPressure:         view.getFloat32(10, true),
            HumidityTemperature: view.getFloat32(14, true),
            Humidity:            view.getFloat32(18, true),
            LightALS:            view.getUint32(22,  true), 
            GASCO2:              view.getFloat32(26, true),
            GASTemperature:      view.getFloat32(30, true),
            GASHumidity:         view.getFloat32(34, true),
            GASNH3:              view.getFloat32(38, true),
            GASCO:               view.getFloat32(42, true),
            GASNO2:              view.getFloat32(46, true),
            BoardTemperature:    view.getFloat32(50, true),
            PT100Temperature:    view.getFloat32(54, true)
        };
    } else if (packetType === 2) {
        messageDetail = "weight_telemetry";
        const samples = [];
        for (let i = 6; i + 1 < bytes.length; i += 2) {
            samples.push(view.getUint16(i, true)); 
        }
        extractedData = {
            count: samples.length,
            mean_weight: samples.reduce((a, b) => a + b, 0) / samples.length
        };
    } else if (packetType === 4) {
        messageDetail = "device_startup";
        extractedData = {
            hardware_mac: frameHex.slice(4, 20), 
            firmware: view.getUint16(10, true) 
        };
    } else if (packetType === 7) {
        messageDetail = "lamination_telemetry";
        extractedData = {
            hw_type: view.getUint8(2),
            firmware: view.getUint16(3, true),
            lux: Math.round(view.getFloat32(6, true)) // Parses 0x42F9FFFF as Float32 (124.99) and rounds to 125
        };
    } else if (packetType === 8) {
        messageDetail = "weight_spot";
        extractedData = {
            hw_type: view.getUint8(2),
            firmware: view.getUint16(3, true),
            weight_g: view.getInt16(6, true) // Parsed as signed 16-bit to allow for negative scale tare drift
        };
    }

    // 5. BUILD THE FAI CLOUD ENVELOPE
    out.push({
        topic: `gateway/${gatewayId}/tinymesh/out`,
        payload: {
            "_meta": { "received": new Date().toISOString() },
            "block": 0,
            "data": JSON.stringify(extractedData), 
            "detail": messageDetail,               
            "hops": hops,
            "latency": latency,
            "network_lvl": networkLvl,
            "packet_num": Math.floor(Math.random() * 65535),
            "rssi": trueRssi, 
            "sid": TARGET_CLOUD_SID,
            "type": "event",
            "uid": dynamicUid,  
            "raw_hex": frameHex 
        }
    });
}

context.set('buf', buf);

if (out.length === 0) return null;
if (out.length === 1) return out[0];
return [out];

const gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

if (!Buffer.isBuffer(msg.payload)) {
    return null;
}

let buf = context.get("emcTinyMeshBuffer");

if (!Buffer.isBuffer(buf)) {
    buf = Buffer.alloc(0);
}

buf = Buffer.concat([buf, msg.payload]);

const messages = [];

while (buf.length > 0) {
    const frameLength = buf[0];

    // Reject implausible values and move forward one byte.
    if (frameLength < 10 || frameLength > 200) {
        buf = buf.subarray(1);
        continue;
    }

    if (buf.length < frameLength) {
        break;
    }

    const frame = buf.subarray(0, frameLength);
    buf = buf.subarray(frameLength);

    // New TinyMesh EMC firmware frame.
    if (frameLength === 78) {
        messages.push({
            topic: `gateway/${gatewaySerial}/tinymesh/rx`,
            payload: {
                received: new Date().toISOString(),
                frame_length: frameLength,
                sequence: frame.length > 13 ? frame[13] : null
            }
        });
    }
}

context.set("emcTinyMeshBuffer", buf);

return messages.length ? [messages] : null;

const gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

if (!Buffer.isBuffer(msg.payload)) {
    try {
        msg.payload = Buffer.from(msg.payload);
    } catch (err) {
        node.error("wMBus payload is not a Buffer", msg);
        return null;
    }
}

const frame = msg.payload;

if (frame.length < 11) {
    node.warn(`Discarding short wMBus frame: ${frame.length} bytes`);
    return null;
}

const sequence = (context.get("sequence") || 0) + 1;
context.set("sequence", sequence);

const lField = frame[0];
const cField = frame[1];
const manufacturerValue = frame[2] | (frame[3] << 8);

const manufacturer =
    String.fromCharCode(((manufacturerValue >> 10) & 0x1f) + 64) +
    String.fromCharCode(((manufacturerValue >> 5) & 0x1f) + 64) +
    String.fromCharCode((manufacturerValue & 0x1f) + 64);

const serialNumber = Buffer.from([
    frame[7],
    frame[6],
    frame[5],
    frame[4]
]).toString("hex").toUpperCase();

msg.topic = `gateway/${gatewaySerial}/wmbus/out`;
msg.payload = {
    "_meta": {
        "received": new Date().toISOString(),
        "receiver_id": "RC1180-B400T7S7",
        "byte_length": frame.length,
        "emc_sequence": sequence
    },
    "data": {
        "LField": lField,
        "CField": cField,
        "MField": manufacturerValue,
        "Manufacturer": manufacturer,
        "SerialNumber": serialNumber,
        "Version": frame[8],
        "DeviceType": frame[9],
        "CIField": frame[10]
    },
    "raw": frame.toString("base64"),
    "hex": frame.toString("hex").toUpperCase(),
    "type": "wmbus"
};

node.status({
    fill: "green",
    shape: "dot",
    text: `${frame.length} bytes · #${sequence}`
});

return msg;

const registers = Array.isArray(msg.payload?.data)
    ? msg.payload.data
    : Array.isArray(msg.payload)
        ? msg.payload
        : null;

if (!registers || registers.length < 2) {
    node.warn("Modbus response did not contain two registers");
    return null;
}

const gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";
const sequence = (context.get("sequence") || 0) + 1;
const received = new Date().toISOString();

context.set("sequence", sequence);

// JavaScript bitwise operations produce a signed 32-bit value.
const weight = (registers[0] << 16) | registers[1];

msg.topic = `gateway/${gatewaySerial}/modbus/silo1/emc`;
msg.payload = {
    received,
    sequence,
    status: "ok",
    interface: "modbus-rtu",
    device: "ADS301-silo-1",
    unit_id: 1,
    function: "read-holding-registers",
    register: 40,
    quantity: 2,
    registers: [registers[0], registers[1]],
    weight_raw: weight
};

node.status({
    fill: "green",
    shape: "dot",
    text: `OK #${sequence}`
});

return msg;

const gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";
const errors = (context.get("errors") || 0) + 1;
context.set("errors", errors);

let detail = "Modbus read failed";

try {
    if (msg.error?.message) detail = msg.error.message;
    else if (msg.payload?.message) detail = msg.payload.message;
    else if (typeof msg.payload === "string") detail = msg.payload;
} catch (_) {
    // Keep default detail.
}

msg.topic = `gateway/${gatewaySerial}/modbus/silo1/emc/error`;
msg.payload = {
    received: new Date().toISOString(),
    status: "error",
    error_count: errors,
    interface: "modbus-rtu",
    device: "ADS301-silo-1",
    unit_id: 1,
    register: 40,
    detail
};

node.status({
    fill: "red",
    shape: "ring",
    text: `Error #${errors}`
});

return msg;
